fn host_recovery_store_mode_v1() -> String {
    HOST_RECOVERY_STORE_MODE_MEMORY_V1.to_string()
}

fn host_recovery_store_backend_v1() -> &'static str {
    HOST_RECOVERY_STORE_BACKEND_JSON_V1
}

fn host_recovery_store_enabled_v1() -> bool {
    true
}

fn host_recovery_store_boundary_json_v1(store_path: &Path) -> Value {
    let mode = host_recovery_store_mode_v1();
    let backend = host_recovery_store_backend_v1();
    serde_json::json!({
        "network_recovery_checkpoint_owner": "novovm_host",
        "network_recovery_checkpoint_enabled": host_recovery_store_enabled_v1(),
        "network_recovery_checkpoint_mode": mode,
        "network_recovery_checkpoint_backend": backend,
        "network_recovery_checkpoint_role": NETWORK_RECOVERY_CHECKPOINT_ROLE_DIAGNOSTICS_ONLY_V1,
        "network_recovery_checkpoint_is_transaction_truth": false,
        "network_recovery_checkpoint_signoff_scope": NETWORK_RECOVERY_CHECKPOINT_SIGNOFF_SCOPE_V1,
        "network_recovery_checkpoint_path": store_path.display().to_string(),
        "network_transport_completion_source": NETWORK_TRANSPORT_COMPLETION_SOURCE_V1,
        "transaction_finality_source": TRANSACTION_FINALITY_SOURCE_AOEM_PROOF_V1,
        "aoem_execution_persistence_owner": AOEM_EXECUTION_PERSISTENCE_OWNER_V1,
        "aoem_execution_persistence_is_truth": true,
        "aoem_state_surface_owner": "aoem_runtime_state_surface",
    })
}

fn annotate_host_recovery_store_boundary_v1(value: &mut Value, store_path: &Path) {
    let boundary = host_recovery_store_boundary_json_v1(store_path);
    if let (Some(target), Some(source)) = (value.as_object_mut(), boundary.as_object()) {
        for (key, item) in source {
            target.insert(key.clone(), item.clone());
        }
        target.insert("network_recovery_checkpoint_boundary".to_string(), boundary);
    }
}

fn host_recovery_store_probe_v1(store_path: &Path) -> Value {
    serde_json::json!({
        "method": "nov_getNetworkRecoveryCheckpointProbe",
        "network_recovery_checkpoint_opened": false,
        "network_recovery_checkpoint_probe_skipped": true,
        "network_recovery_checkpoint_probe_skipped_reason": "network_recovery_checkpoint_is_memory_first",
        "network_recovery_checkpoint_enabled": host_recovery_store_enabled_v1(),
        "network_recovery_checkpoint_mode": HOST_RECOVERY_STORE_MODE_MEMORY_V1,
        "network_recovery_checkpoint_backend": HOST_RECOVERY_STORE_BACKEND_JSON_V1,
        "network_recovery_checkpoint_role": NETWORK_RECOVERY_CHECKPOINT_ROLE_DIAGNOSTICS_ONLY_V1,
        "network_recovery_checkpoint_is_transaction_truth": false,
        "network_recovery_checkpoint_signoff_scope": NETWORK_RECOVERY_CHECKPOINT_SIGNOFF_SCOPE_V1,
        "network_recovery_checkpoint_path": store_path.display().to_string(),
        "network_transport_completion_source": NETWORK_TRANSPORT_COMPLETION_SOURCE_V1,
        "transaction_finality_source": TRANSACTION_FINALITY_SOURCE_AOEM_PROOF_V1,
        "aoem_execution_persistence_owner": AOEM_EXECUTION_PERSISTENCE_OWNER_V1,
        "aoem_execution_persistence_is_truth": true,
        "network_recovery_checkpoint_total_estimated_memory_bytes": 0u64,
        "network_recovery_checkpoint_cache_estimated_bytes": 0u64,
        "network_recovery_checkpoint_memtable_estimated_bytes": 0u64,
        "network_recovery_checkpoint_index_filter_estimated_bytes": 0u64,
        "network_recovery_checkpoint_probe_supported": false,
    })
}

fn get_host_recovery_store_recovery_probe_v1(store_path: &Path) -> Result<Value> {
    let backend = host_recovery_store_backend_v1();
    let previous_backend = std::env::var_os("NOVOVM_NATIVE_EXECUTION_STORE_BACKEND");
    std::env::set_var("NOVOVM_NATIVE_EXECUTION_STORE_BACKEND", backend);
    let result = get_nov_native_execution_store_recovery_probe_v1(store_path);
    match previous_backend {
        Some(value) => std::env::set_var("NOVOVM_NATIVE_EXECUTION_STORE_BACKEND", value),
        None => std::env::remove_var("NOVOVM_NATIVE_EXECUTION_STORE_BACKEND"),
    }
    let mut probe = result?;
    annotate_host_recovery_store_boundary_v1(&mut probe, store_path);
    Ok(probe)
}

#[cfg(test)]
fn restore_env_var_v1(name: &str, value: Option<std::ffi::OsString>) {
    match value {
        Some(raw) => std::env::set_var(name, raw),
        None => std::env::remove_var(name),
    }
}

#[cfg(test)]
fn nonzero_output_with_stderr_v1(stderr: &[u8]) -> Output {
    let mut output = if cfg!(windows) {
        Command::new("cmd")
            .args(["/C", "exit 1"])
            .output()
            .expect("spawn cmd")
    } else {
        Command::new("sh")
            .args(["-c", "exit 1"])
            .output()
            .expect("spawn sh")
    };
    output.stderr = stderr.to_vec();
    output
}

#[test]
fn full_async_host_recovery_store_defaults_to_memory_not_rocksdb() {
    let prev_full_async = std::env::var_os(NOV_NATIVE_AOEM_FULL_ASYNC_RUNTIME_ENGINE_ENV);
    std::env::set_var(NOV_NATIVE_AOEM_FULL_ASYNC_RUNTIME_ENGINE_ENV, "1");

    let mode = host_recovery_store_mode_v1();
    assert_eq!(mode, HOST_RECOVERY_STORE_MODE_MEMORY_V1);
    assert_eq!(host_recovery_store_backend_v1(), "json");

    restore_env_var_v1(
        NOV_NATIVE_AOEM_FULL_ASYNC_RUNTIME_ENGINE_ENV,
        prev_full_async,
    );
}

#[test]
fn host_recovery_store_has_no_rocksdb_mode_gate() {
    let prev_full_async = std::env::var_os(NOV_NATIVE_AOEM_FULL_ASYNC_RUNTIME_ENGINE_ENV);
    std::env::set_var(NOV_NATIVE_AOEM_FULL_ASYNC_RUNTIME_ENGINE_ENV, "1");

    let mode = host_recovery_store_mode_v1();
    let probe = host_recovery_store_probe_v1(Path::new("receiver-store.json"));
    assert_eq!(mode, HOST_RECOVERY_STORE_MODE_MEMORY_V1);
    assert_eq!(host_recovery_store_backend_v1(), "json");
    assert_eq!(
        probe["network_recovery_checkpoint_opened"].as_bool(),
        Some(false)
    );
    assert_eq!(
        probe["network_recovery_checkpoint_probe_skipped"].as_bool(),
        Some(true)
    );
    assert_eq!(
        probe["network_recovery_checkpoint_probe_skipped_reason"].as_str(),
        Some("network_recovery_checkpoint_is_memory_first")
    );

    restore_env_var_v1(
        NOV_NATIVE_AOEM_FULL_ASYNC_RUNTIME_ENGINE_ENV,
        prev_full_async,
    );
}

#[test]
fn host_recovery_store_boundary_marks_host_truth_false_and_aoem_truth_true() {
    let prev_full_async = std::env::var_os(NOV_NATIVE_AOEM_FULL_ASYNC_RUNTIME_ENGINE_ENV);
    std::env::set_var(NOV_NATIVE_AOEM_FULL_ASYNC_RUNTIME_ENGINE_ENV, "1");

    let boundary = host_recovery_store_boundary_json_v1(Path::new("receiver-store.json"));
    assert_eq!(
        boundary["aoem_execution_persistence_owner"].as_str(),
        Some(AOEM_EXECUTION_PERSISTENCE_OWNER_V1)
    );
    assert_eq!(
        boundary["aoem_execution_persistence_is_truth"].as_bool(),
        Some(true)
    );
    assert_eq!(
        boundary["transaction_finality_source"].as_str(),
        Some(TRANSACTION_FINALITY_SOURCE_AOEM_PROOF_V1)
    );
    assert_eq!(
        boundary["network_recovery_checkpoint_role"].as_str(),
        Some(NETWORK_RECOVERY_CHECKPOINT_ROLE_DIAGNOSTICS_ONLY_V1)
    );
    assert_eq!(
        boundary["network_recovery_checkpoint_is_transaction_truth"].as_bool(),
        Some(false)
    );
    assert_eq!(
        boundary["network_recovery_checkpoint_mode"].as_str(),
        Some(HOST_RECOVERY_STORE_MODE_MEMORY_V1)
    );

    restore_env_var_v1(
        NOV_NATIVE_AOEM_FULL_ASYNC_RUNTIME_ENGINE_ENV,
        prev_full_async,
    );
}

#[test]
fn novorudp_transport_boundary_rules_are_documented() {
    let boundary = include_str!("../../../../docs/NOVORUDP_BOUNDARY.md");

    for required in [
        "NOVORUDP must be an independent transport layer.",
        "Transport frames must not depend on `EvmNative::Transactions`.",
        "Repair must not be encoded as a business transaction frame.",
        "Business payloads must not participate in repair classification.",
        "Transport ACK must confirm packet/object delivery only.",
        "Transport ACK must not depend on AOEM ledger close.",
        "AOEM may consume delivered payloads, but AOEM must not drive transport receive accounting.",
        "Network-only delivery sustained.",
        "Business payload delivery sustained.",
        "AOEM ledger sustained.",
        "legacy compatibility or attribution only",
    ] {
        assert!(
            boundary.contains(required),
            "NOVORUDP boundary document is missing required rule: {required}"
        );
    }
}

