    #[test]
    fn full_async_receiver_done_ack_fast_path_triggers_before_final_report() {
        let listener = UdpSocket::bind("127.0.0.1:0").expect("ack listener");
        listener
            .set_read_timeout(Some(Duration::from_millis(250)))
            .expect("ack read timeout");
        let target = listener.local_addr().expect("listener addr").to_string();
        let path =
            std::env::temp_dir().join(format!("novovm-receiver-done-fast-path-{}.json", now_ms()));
        with_env_var(
            "NOVOVM_NATIVE_PIPELINE_ACK_REPORT_PATH",
            path.to_str(),
            || {
                with_env_var("NOVOVM_NETWORK_PROFILE", Some("local_smoke"), || {
                    with_env_var(
                        "NOVOVM_NATIVE_PIPELINE_ACK_TARGET_ADDR",
                        Some(target.as_str()),
                        || {
                            with_env_var(
                                "NOVOVM_NATIVE_PIPELINE_UDP_ACK_ENABLED",
                                Some("1"),
                                || {
                                    with_env_var(
                                        "NOVOVM_RECEIVER_DONE_ACK_FAST_PATH_BURST_COUNT",
                                        Some("3"),
                                        || {
                                            with_env_var(
                                            "NOVOVM_RECEIVER_DONE_ACK_FAST_PATH_BURST_INTERVAL_MS",
                                            Some("0"),
                                            || {
                                                let status = emit_receiver_done_ack_fast_path_v1(
                                                    4,
                                                    64,
                                                    40,
                                                    Instant::now(),
                                                    None,
                                                );
                                                assert!(status.enabled);
                                                assert!(status.triggered);
                                                assert_eq!(status.burst_count, 3);
                                                assert_eq!(status.send_attempt_count, 3);
                                                assert_eq!(status.send_ok_count, 3);
                                                assert_eq!(status.send_error_count, 0);
                                                assert!(status.before_final_report);
                                                assert!(status.before_diagnostics_flush);

                                                let mut received_done = false;
                                                let mut buf = [0u8; 4096];
                                                for _ in 0..3 {
                                                    let Ok((len, _)) = listener.recv_from(&mut buf)
                                                    else {
                                                        continue;
                                                    };
                                                    let packet =
                                                        serde_json::from_slice::<Value>(&buf[..len])
                                                            .expect("receiver done ack json");
                                                    received_done |= packet["receiver_done"]
                                                        .as_bool()
                                                        .unwrap_or(false);
                                                }
                                                assert!(received_done);
                                            },
                                        )
                                        },
                                    )
                                },
                            )
                        },
                    )
                })
            },
        );
        let _ = fs::remove_file(path);
    }
    #[test]
    fn full_async_ack_plane_latches_receiver_done_ack_even_when_epoch_is_stale() {
        let mut plane = FullAsyncAckDrainPumpStateV1::default();
        merge_full_async_ack_plane_state_v1(
            &mut plane,
            UdpAckStateV1 {
                received_count: 1,
                latest_epoch: 20,
                latest_missing_count: 4,
                latest_ranges: vec![MissingRangeV1 {
                    start: 4,
                    end_inclusive: 7,
                }],
                receiver_done: false,
                ..UdpAckStateV1::default()
            },
            480,
            100,
        );
        merge_full_async_ack_plane_state_v1(
            &mut plane,
            UdpAckStateV1 {
                received_count: 1,
                latest_epoch: 19,
                latest_missing_count: 0,
                receiver_done: true,
                ..UdpAckStateV1::default()
            },
            480,
            110,
        );

        assert!(plane.receiver_done_latched);
        assert!(plane.caught_up_latched);
        assert_eq!(plane.receiver_done_latch_epoch, Some(19));
        assert_eq!(
            plane.caught_up_latch_source.as_deref(),
            Some("receiver_done_ack")
        );
        assert_eq!(plane.caught_up_latch_missing_count, Some(0));
        assert_eq!(plane.receiver_done_stale_drop_count, 1);
        assert_eq!(
            plane
                .receiver_done_sticky_sample
                .as_ref()
                .map(|ack| ack.receiver_done),
            Some(true)
        );
        assert_eq!(
            plane
                .latest_ack
                .as_ref()
                .map(|ack| ack.latest_missing_count),
            Some(4)
        );
    }

