    #[test]
    fn sender_repair_coverage_computes_ack_overlap_and_duplicate_waste() {
        let latest_ack_missing = vec![
            MissingRangeV1 {
                start: 100,
                end_inclusive: 199,
            },
            MissingRangeV1 {
                start: 300,
                end_inclusive: 399,
            },
        ];
        let repair_sent = vec![
            MissingRangeV1 {
                start: 100,
                end_inclusive: 149,
            },
            MissingRangeV1 {
                start: 100,
                end_inclusive: 149,
            },
            MissingRangeV1 {
                start: 500,
                end_inclusive: 549,
            },
        ];
        let report = novorudp_sender_repair_coverage_report_v1(
            latest_ack_missing.as_slice(),
            repair_sent.as_slice(),
            1_000,
            150,
            8,
        );

        assert_eq!(
            report["sender_latest_ack_missing_sequence_count"].as_u64(),
            Some(200)
        );
        assert_eq!(
            report["sender_latest_ack_missing_count"].as_u64(),
            Some(200)
        );
        let expected_latest_digest = missing_ranges_digest_v1(latest_ack_missing.as_slice(), 1_000);
        assert_eq!(
            report["sender_latest_ack_missing_digest"].as_str(),
            Some(expected_latest_digest.as_str())
        );
        assert_eq!(
            report["sender_repair_sent_unique_sequence_count"].as_u64(),
            Some(100)
        );
        assert_eq!(report["sender_final_repair_sent_count"].as_u64(), Some(100));
        let expected_repair_digest = missing_ranges_digest_v1(
            normalize_missing_ranges(repair_sent.as_slice(), 1_000).as_slice(),
            1_000,
        );
        assert_eq!(
            report["sender_final_repair_sent_digest"].as_str(),
            Some(expected_repair_digest.as_str())
        );
        assert_eq!(
            report["sender_repair_sent_overlap_ack_missing_count"].as_u64(),
            Some(50)
        );
        assert_eq!(
            report["sender_repair_sent_duplicate_sequence_count"].as_u64(),
            Some(50)
        );
        assert_eq!(
            report["repair_duplicate_waste_ratio_bps"].as_u64(),
            Some(3333)
        );
        assert_eq!(report["repair_duplicate_ratio_x1000"].as_u64(), Some(333));
        assert_eq!(
            report["repair_latest_missing_coverage_ratio_x1000"].as_u64(),
            Some(250)
        );
    }

