    #[test]
    fn missing_digest_delta_classifies_canonical_same_sequence_set() {
        let previous = vec![
            MissingRangeV1 {
                start: 10,
                end_inclusive: 19,
            },
            MissingRangeV1 {
                start: 20,
                end_inclusive: 29,
            },
        ];
        let current = vec![MissingRangeV1 {
            start: 10,
            end_inclusive: 29,
        }];

        let delta = missing_digest_delta_v1(previous.as_slice(), current.as_slice(), 100);

        assert_eq!(delta.added_count, 0);
        assert_eq!(delta.removed_count, 0);
        assert_eq!(delta.overlap_count, 20);
        assert_eq!(delta.jaccard_bps, 10_000);
        assert!(delta.same_range_set);
        assert!(delta.same_sequence_set);
    }

    #[test]
    fn missing_digest_delta_reports_real_missing_change() {
        let previous = vec![MissingRangeV1 {
            start: 10,
            end_inclusive: 29,
        }];
        let current = vec![MissingRangeV1 {
            start: 20,
            end_inclusive: 39,
        }];

        let delta = missing_digest_delta_v1(previous.as_slice(), current.as_slice(), 100);

        assert_eq!(delta.previous_count, 20);
        assert_eq!(delta.current_count, 20);
        assert_eq!(delta.added_count, 10);
        assert_eq!(delta.removed_count, 10);
        assert_eq!(delta.overlap_count, 10);
        assert_eq!(delta.overlap_ratio_bps, 5_000);
        assert_eq!(delta.jaccard_bps, 3_333);
        assert!(!delta.same_sequence_set);
        assert!(!delta.same_min_max);
    }

    #[test]
    fn monotonic_shrink_retry_delta_requires_prior_coverage_and_no_added_sequences() {
        let previous = vec![MissingRangeV1 {
            start: 0,
            end_inclusive: 99,
        }];
        let current = vec![MissingRangeV1 {
            start: 0,
            end_inclusive: 79,
        }];
        let covered = previous.clone();

        let delta = monotonic_shrink_retry_delta_v1(
            previous.as_slice(),
            current.as_slice(),
            covered.as_slice(),
            480,
            8_000,
        )
        .expect("high-overlap shrink with prior coverage should be gated");

        assert_eq!(delta.added_count, 0);
        assert_eq!(delta.removed_count, 20);
        assert_eq!(delta.overlap_ratio_bps, 10_000);
        assert!(monotonic_shrink_retry_delta_v1(
            previous.as_slice(),
            current.as_slice(),
            &[],
            480,
            8_000,
        )
        .is_none());

        let expanded = vec![MissingRangeV1 {
            start: 0,
            end_inclusive: 119,
        }];
        assert!(monotonic_shrink_retry_delta_v1(
            previous.as_slice(),
            expanded.as_slice(),
            covered.as_slice(),
            480,
            8_000,
        )
        .is_none());
    }

