    #[test]
    fn production_sender_starts_done_deadline_after_seen_all() {
        with_env_var("NOVOVM_AOEM_FULL_ASYNC_RUNTIME_ENGINE", Some("1"), || {
            with_env_var("NOVOVM_NETWORK_PROFILE", Some("local_smoke"), || {
                with_env_var(
                    "NOVOVM_NATIVE_PIPELINE_FINAL_ACK_WAIT_MS",
                    Some("50"),
                    || {
                        with_env_var(
                            "NOVOVM_NATIVE_PIPELINE_FINAL_ACK_POLL_MS",
                            Some("1"),
                            || {
                                with_env_var(
                                    "NOVOVM_NATIVE_PIPELINE_RECEIVER_PROGRESS_DEADLINE_MS",
                                    Some("500"),
                                    || {
                                        with_sender_hard_timeout_env(800, || {
                                            let chain_id = 92_033;
                                            let tx_count = 4;
                                            let sender_addr =
                                                reserve_udp_addr().expect("sender addr");
                                            let receiver_addr =
                                                reserve_udp_addr().expect("receiver addr");
                                            let ack_bind_addr =
                                                reserve_udp_addr().expect("ack bind addr");
                                            let ack_target_addr = ack_bind_addr.clone();
                                            let ack_thread = std::thread::spawn(move || {
                                                std::thread::sleep(Duration::from_millis(20));
                                                let socket = UdpSocket::bind("127.0.0.1:0")
                                                    .expect("progress ack sender socket");
                                                let mut ack = receiver_ack_report_value(
                                                    tx_count, tx_count, 64, 41,
                                                );
                                                ack["receiver_done"] = serde_json::json!(false);
                                                let _ = socket.send_to(
                                                    ack.to_string().as_bytes(),
                                                    ack_target_addr,
                                                );
                                            });

                                            let report = run_sender(
                                                chain_id,
                                                tx_count,
                                                1,
                                                2,
                                                sender_addr.as_str(),
                                                receiver_addr.as_str(),
                                                FaultConfigV1 {
                                                    enabled: false,
                                                    loss_bps: 0,
                                                    duplicate_bps: 0,
                                                    delay_ms: 0,
                                                    reorder_bps: 0,
                                                    seed: 0,
                                                },
                                                sender_timeout_sustained_config(tx_count),
                                                sender_timeout_tail_repair_config(),
                                                default_udp_send_retry_config(),
                                                UdpAckConfigV1 {
                                                    enabled: true,
                                                    bind_addr: ack_bind_addr,
                                                    target_addr: None,
                                                    recv_timeout_ms: 0,
                                                },
                                                sender_timeout_novorudp_config(),
                                            )
                                            .expect(
                                                "sender must return final done deadline report",
                                            );
                                            let _ = ack_thread.join();

                                            assert_eq!(report["accepted"].as_bool(), Some(false));
                                            assert_eq!(
                                            report["fail_reason"].as_str(),
                                            Some("receiver_done_ack_not_observed_after_caught_up")
                                        );
                                            assert_eq!(
                                                report["sender_receiver_progress_seen"].as_bool(),
                                                Some(true)
                                            );
                                            assert_eq!(
                                                report["sender_receiver_progress_seen_all"]
                                                    .as_bool(),
                                                Some(true)
                                            );
                                            assert_eq!(
                                                report["receiver_progress_deadline_exceeded"]
                                                    .as_bool(),
                                                Some(false)
                                            );
                                            assert_eq!(
                                                report
                                                    ["final_ack_deadline_exceeded_after_progress"]
                                                    .as_bool(),
                                                Some(true)
                                            );
                                            assert_eq!(
                                                report
                                                    ["sender_final_done_ack_deadline_start_reason"]
                                                    .as_str(),
                                                Some("latest_ack_missing_zero")
                                            );
                                        })
                                    },
                                );
                            },
                        )
                    },
                )
            })
        });
    }

    #[test]
    fn full_async_sender_ack_plane_receives_receiver_done_ack() {
        with_env_var("NOVOVM_AOEM_FULL_ASYNC_RUNTIME_ENGINE", Some("1"), || {
            with_env_var("NOVOVM_NETWORK_PROFILE", Some("local_smoke"), || {
                with_env_var(
                    "NOVOVM_NATIVE_PIPELINE_FINAL_ACK_WAIT_MS",
                    Some("1000"),
                    || {
                        with_env_var(
                            "NOVOVM_NATIVE_PIPELINE_FINAL_ACK_POLL_MS",
                            Some("1"),
                            || {
                                with_sender_hard_timeout_env(500, || {
                                    let chain_id = 92_004;
                                    let tx_count = 4;
                                    let sender_addr = reserve_udp_addr().expect("sender addr");
                                    let receiver_addr = reserve_udp_addr().expect("receiver addr");
                                    let ack_bind_addr = reserve_udp_addr().expect("ack bind addr");
                                    let ack_target_addr = ack_bind_addr.clone();
                                    let ack_thread = std::thread::spawn(move || {
                                        std::thread::sleep(Duration::from_millis(20));
                                        let socket = UdpSocket::bind("127.0.0.1:0")
                                            .expect("receiver done ack sender socket");
                                        let ack =
                                            receiver_ack_report_value(tx_count, tx_count, 64, 99);
                                        let _ = socket
                                            .send_to(ack.to_string().as_bytes(), ack_target_addr);
                                    });

                                    let report = run_sender(
                                        chain_id,
                                        tx_count,
                                        1,
                                        2,
                                        sender_addr.as_str(),
                                        receiver_addr.as_str(),
                                        FaultConfigV1 {
                                            enabled: false,
                                            loss_bps: 0,
                                            duplicate_bps: 0,
                                            delay_ms: 0,
                                            reorder_bps: 0,
                                            seed: 0,
                                        },
                                        sender_timeout_sustained_config(tx_count),
                                        sender_timeout_tail_repair_config(),
                                        default_udp_send_retry_config(),
                                        UdpAckConfigV1 {
                                            enabled: true,
                                            bind_addr: ack_bind_addr,
                                            target_addr: None,
                                            recv_timeout_ms: 0,
                                        },
                                        sender_timeout_novorudp_config(),
                                    )
                                    .expect("sender must accept receiver_done ack");
                                    let _ = ack_thread.join();

                                    assert_eq!(report["accepted"].as_bool(), Some(true));
                                    assert_eq!(report["fail_reason"], Value::Null);
                                    assert_eq!(
                                        report["runtime_profile"].as_str(),
                                        Some("production")
                                    );
                                    assert_eq!(
                                        report["final_ack_wait_profile"].as_str(),
                                        Some("production")
                                    );
                                    assert_eq!(
                                        report["final_ack_wait_source"].as_str(),
                                        Some("env_override")
                                    );
                                    assert_eq!(report["final_ack_wait_ms"].as_u64(), Some(1000));
                                    assert_eq!(
                                        report["production_low_latency_signoff"].as_bool(),
                                        Some(true)
                                    );
                                    assert_eq!(
                                        report["sender_finalization_wait_mode"].as_str(),
                                        Some("production_low_latency_deadline")
                                    );
                                    assert_eq!(
                                        report["sender_final_ack_fast_drain_enabled"].as_bool(),
                                        Some(true)
                                    );
                                    assert_eq!(
                                        report["sender_final_ack_fast_drain_receiver_done_seen"]
                                            .as_bool(),
                                        Some(true)
                                    );
                                    assert_eq!(
                                        report["production_final_ack_deadline_exceeded"].as_bool(),
                                        Some(false)
                                    );
                                    assert_eq!(
                                        report["tail_repair"]["tail_repair_completion_reason"]
                                            .as_str(),
                                        Some("receiver_done_ack")
                                    );
                                    assert_eq!(
                                        report["tail_repair"]["latest_ack_missing_count"].as_u64(),
                                        Some(0)
                                    );
                                    assert_eq!(
                                        report["tail_repair"]["latest_ack_receiver_done"].as_bool(),
                                        Some(true)
                                    );
                                    assert_eq!(
                                        report["sender_ack_final_sample_source"].as_str(),
                                        Some("ack_plane_receiver_done")
                                    );
                                    assert_eq!(
                                        report["sender_ack_final_sample_is_null"].as_bool(),
                                        Some(false)
                                    );
                                    assert_eq!(
                                        report["sender_ack_receiver_done_seen"].as_bool(),
                                        Some(true)
                                    );
                                    assert_eq!(
                                        report["sender_ack_receiver_done_epoch"].as_u64(),
                                        Some(99)
                                    );
                                    assert_eq!(
                                        report["full_async_ack_drain_dedicated_pump_enabled"]
                                            .as_bool(),
                                        Some(true)
                                    );
                                    assert_eq!(
                                        report["ack_plane_thread_or_task_started"].as_bool(),
                                        Some(true)
                                    );
                                });
                            },
                        )
                    },
                )
            })
        });
    }

    #[test]
    fn full_async_sender_final_ack_overrides_stale_missing_sample() {
        let result = reconcile_sender_final_ack_with_latest_missing_v1(
            SenderFinalAckReconciliationInputV1 {
                sender_completed: true,
                tail_repair_enabled: true,
                receiver_done_ack_required: true,
                latest_ack_receiver_done: true,
                latest_ack_missing_count: Some(0),
                repair_coverage_gap_count: 1708,
                final_ack_received_after_repair: true,
                fallback_fail_reason: Some("receiver_repair_incomplete"),
            },
        );

        assert!(result.accepted);
        assert!(result.receiver_done_ack_seen);
        assert_eq!(result.final_missing_count, Some(0));
        assert_eq!(result.final_sample_source, "ack_plane_receiver_done");
        assert_eq!(result.finalization_reason, "receiver_done_ack_after_grace");
        assert_eq!(result.fail_reason, None);
        assert!(!result.repair_coverage_gap_blocks_final);
        assert!(result.repair_coverage_gap_ignored_after_receiver_done);
        assert!(result.receiver_done_ack_overrides_repair_incomplete);
    }

