    let mut repair_digest_changed_high_overlap_count = 0u64;
    let mut repair_digest_changed_last_overlap_ratio_bps = 0u64;
    let mut repair_digest_changed_last_jaccard_bps = 0u64;
    let mut repair_monotonic_shrink_detected_count = 0u64;
    let mut repair_monotonic_shrink_suppressed_count = 0u64;
    let mut repair_monotonic_shrink_controlled_retry_count = 0u64;
    let mut repair_monotonic_shrink_added_sequence_count = 0u64;
    let mut repair_monotonic_shrink_removed_sequence_count = 0u64;
    let mut repair_monotonic_shrink_overlap_bps_sum = 0u64;
    let mut repair_monotonic_shrink_event_count = 0u64;
    let mut repair_monotonic_shrink_wait_ack_count = 0u64;
    let mut repair_monotonic_shrink_timeout_escape_count = 0u64;
    let mut repair_monotonic_shrink_last_overlap_bps = 0u64;
    macro_rules! monotonic_shrink_retry_blocked {
        ($current_ranges:expr) => {{
            let escape_retry_due = repair_same_snapshot_hard_freeze.escape_retry_due(
                Duration::from_millis(repair_missing_digest_freeze_escape_after_ms),
            );
            let shrink_delta = monotonic_shrink_retry_delta_v1(
                repair_suppression_active_missing_snapshot.as_slice(),
                $current_ranges,
                repair_suppression_sent_ranges_for_snapshot.as_slice(),
                tx_count,
                repair_monotonic_shrink_min_overlap_bps,
            );
            if let Some(delta) = shrink_delta {
                let current_count = missing_ranges_count($current_ranges);
                repair_monotonic_shrink_detected_count =
                    repair_monotonic_shrink_detected_count.saturating_add(current_count);
                repair_monotonic_shrink_event_count =
                    repair_monotonic_shrink_event_count.saturating_add(1);
                repair_monotonic_shrink_added_sequence_count =
                    repair_monotonic_shrink_added_sequence_count.saturating_add(delta.added_count);
                repair_monotonic_shrink_removed_sequence_count =
                    repair_monotonic_shrink_removed_sequence_count
                        .saturating_add(delta.removed_count);
                repair_monotonic_shrink_overlap_bps_sum =
                    repair_monotonic_shrink_overlap_bps_sum.saturating_add(delta.overlap_ratio_bps);
                repair_monotonic_shrink_last_overlap_bps = delta.overlap_ratio_bps;
                if escape_retry_due {
                    repair_monotonic_shrink_controlled_retry_count =
                        repair_monotonic_shrink_controlled_retry_count
                            .saturating_add(current_count);
                    repair_monotonic_shrink_timeout_escape_count =
                        repair_monotonic_shrink_timeout_escape_count.saturating_add(1);
                    false
                } else {
                    repair_monotonic_shrink_suppressed_count =
                        repair_monotonic_shrink_suppressed_count.saturating_add(current_count);
                    repair_monotonic_shrink_wait_ack_count =
                        repair_monotonic_shrink_wait_ack_count.saturating_add(1);
                    true
                }
            } else {
                false
            }
        }};
    }
    macro_rules! record_repair_selection_gating_delta {
        ($selected_ranges:expr, $snapshot_ranges:expr, $ack_epoch:expr, $path:expr, $base_retry_due:expr, $retry_due:expr, $unique_coverage_blocks_retry:expr) => {{
            let selected_count = missing_ranges_count($selected_ranges);
            if selected_count > 0 {
                repair_selected_missing_total =
                    repair_selected_missing_total.saturating_add(selected_count);
                repair_selected_missing_per_round_counts.push(selected_count);
                let normalized_snapshot = normalize_missing_ranges($snapshot_ranges, tx_count);
                let digest = missing_ranges_digest_v1($snapshot_ranges, tx_count);
                if repair_last_selection_digest.as_deref() == Some(digest.as_str()) {
                    repair_digest_identity_stable_count =
                        repair_digest_identity_stable_count.saturating_add(selected_count);
                    if repair_last_selection_ack_epoch != Some($ack_epoch) {
                        repair_ack_refresh_before_retry_count =
                            repair_ack_refresh_before_retry_count.saturating_add(selected_count);
                    }
                } else {
                    repair_digest_identity_changed_count =
                        repair_digest_identity_changed_count.saturating_add(selected_count);
                    repair_digest_changed_event_count =
                        repair_digest_changed_event_count.saturating_add(1);
                    if repair_snapshot_fully_covered_v1(
                        normalized_snapshot.as_slice(),
                        repair_suppression_unique_coverage_snapshot.as_slice(),
                        tx_count,
                    ) || $unique_coverage_blocks_retry
                    {
                        repair_digest_changed_after_coverage_count =
                            repair_digest_changed_after_coverage_count
                                .saturating_add(selected_count);
                    }
                    if repair_last_selection_digest.is_some() {
                        let delta = missing_digest_delta_v1(
                            repair_last_selection_ranges.as_slice(),
                            normalized_snapshot.as_slice(),
                            tx_count,
                        );
                        repair_digest_changed_previous_sequence_count =
                            repair_digest_changed_previous_sequence_count
                                .saturating_add(delta.previous_count);
                        repair_digest_changed_current_sequence_count =
                            repair_digest_changed_current_sequence_count
                                .saturating_add(delta.current_count);
                        repair_digest_changed_added_sequence_count =
                            repair_digest_changed_added_sequence_count
                                .saturating_add(delta.added_count);
                        repair_digest_changed_removed_sequence_count =
                            repair_digest_changed_removed_sequence_count
                                .saturating_add(delta.removed_count);
                        repair_digest_changed_overlap_sequence_count =
                            repair_digest_changed_overlap_sequence_count
                                .saturating_add(delta.overlap_count);
                        repair_digest_changed_overlap_ratio_bps_sum =
                            repair_digest_changed_overlap_ratio_bps_sum
                                .saturating_add(delta.overlap_ratio_bps);
                        repair_digest_changed_jaccard_bps_sum =
                            repair_digest_changed_jaccard_bps_sum.saturating_add(delta.jaccard_bps);
                        repair_digest_changed_last_overlap_ratio_bps = delta.overlap_ratio_bps;
                        repair_digest_changed_last_jaccard_bps = delta.jaccard_bps;
                        if delta.same_range_set {
                            repair_digest_changed_same_range_set_count =
                                repair_digest_changed_same_range_set_count
                                    .saturating_add(selected_count);
                        }
                        if delta.same_sequence_set {
                            repair_digest_changed_same_sequence_set_count =
                                repair_digest_changed_same_sequence_set_count
                                    .saturating_add(selected_count);
                            repair_digest_changed_same_missing_count =
                                repair_digest_changed_same_missing_count
                                    .saturating_add(selected_count);
                        }
                        if delta.same_min_max {
                            repair_digest_changed_same_min_max_count =
                                repair_digest_changed_same_min_max_count
                                    .saturating_add(selected_count);
                        }
                        if delta.same_sequence_set && !delta.same_range_set {
                            repair_digest_changed_order_only_count =
                                repair_digest_changed_order_only_count
                                    .saturating_add(selected_count);
                        }
                        if delta.same_sequence_set
                            && repair_last_selection_ack_epoch != Some($ack_epoch)
                        {
                            repair_digest_changed_metadata_only_count =
                                repair_digest_changed_metadata_only_count
                                    .saturating_add(selected_count);
                        }
                        if delta.added_count > 0 || delta.removed_count > 0 {
                            repair_digest_changed_real_missing_delta_count =
                                repair_digest_changed_real_missing_delta_count
                                    .saturating_add(selected_count);
                        }
                        if delta.jaccard_bps >= 9_000 {
                            repair_digest_changed_high_overlap_count =
                                repair_digest_changed_high_overlap_count
                                    .saturating_add(selected_count);
                        }
                    }
                    repair_last_selection_digest = Some(digest);
                    repair_last_selection_ranges = normalized_snapshot;
                }
                repair_last_selection_ack_epoch = Some($ack_epoch);

                if $retry_due {
                    repair_retry_round_enter_count =
                        repair_retry_round_enter_count.saturating_add(selected_count);
                    if $path == "post_primary" {
                        repair_post_primary_retry_enter_count =
                            repair_post_primary_retry_enter_count.saturating_add(selected_count);
                    }
                } else {
                    repair_retry_round_skipped_count =
                        repair_retry_round_skipped_count.saturating_add(selected_count);
                    if $path == "post_primary" {
                        repair_post_primary_retry_skipped_count =
                            repair_post_primary_retry_skipped_count.saturating_add(selected_count);
                    }
                    if $unique_coverage_blocks_retry {
                        repair_retry_round_skip_reason_coverage_seen =
                            repair_retry_round_skip_reason_coverage_seen
                                .saturating_add(selected_count);
                    } else if repair_same_snapshot_hard_freeze.key_matches(
                        $ack_epoch,
                        $snapshot_ranges,
                        tx_count,
                    ) {
                        repair_retry_round_skip_reason_digest_stable =
                            repair_retry_round_skip_reason_digest_stable
                                .saturating_add(selected_count);
                    } else if !$base_retry_due {
                        repair_retry_round_skip_reason_cooldown_or_cap =
                            repair_retry_round_skip_reason_cooldown_or_cap
                                .saturating_add(selected_count);
                    }
                }
            }
        }};
    }
    macro_rules! record_hard_freeze_final_send_diagnostics {
        ($selected_ranges:expr, $snapshot_ranges:expr, $ack_epoch:expr, $path:expr, $blocked_count:expr, $escape_retry_due:expr) => {{
            let selected_count = missing_ranges_count($selected_ranges);
            if selected_count > 0 {
                repair_hard_freeze_eval_count =
                    repair_hard_freeze_eval_count.saturating_add(selected_count);
                repair_hard_freeze_final_send_eval_count =
                    repair_hard_freeze_final_send_eval_count.saturating_add(selected_count);
                match $path {
                    "post_primary" => {
                        repair_hard_freeze_post_primary_eval_count =
                            repair_hard_freeze_post_primary_eval_count
                                .saturating_add(selected_count);
                    }
                    "repair_pump" => {
                        repair_hard_freeze_repair_pump_eval_count =
                            repair_hard_freeze_repair_pump_eval_count
                                .saturating_add(selected_count);
                    }
                    _ => {
                        repair_hard_freeze_miss_reason_path_not_checked =
                            repair_hard_freeze_miss_reason_path_not_checked
                                .saturating_add(selected_count);
                    }
                }
                if $blocked_count > 0 {
                    repair_hard_freeze_hit_count =
                        repair_hard_freeze_hit_count.saturating_add($blocked_count);
                    repair_missing_digest_freeze_block_count =
                        repair_missing_digest_freeze_block_count.saturating_add($blocked_count);
                    repair_hard_freeze_final_send_blocked_count =
                        repair_hard_freeze_final_send_blocked_count.saturating_add($blocked_count);
                    repair_hard_freeze_final_send_allowed_count =
                        repair_hard_freeze_final_send_allowed_count
                            .saturating_add(selected_count.saturating_sub($blocked_count));
                } else if $escape_retry_due
                    && repair_same_snapshot_hard_freeze.key_matches(
                        $ack_epoch,
                        $snapshot_ranges,
                        tx_count,
                    )
                {
                    repair_missing_digest_freeze_escape_retry_count =
                        repair_missing_digest_freeze_escape_retry_count
                            .saturating_add(selected_count);
                    repair_hard_freeze_final_send_allowed_count =
                        repair_hard_freeze_final_send_allowed_count.saturating_add(selected_count);
                } else {
                    repair_hard_freeze_miss_count =
                        repair_hard_freeze_miss_count.saturating_add(selected_count);
                    repair_hard_freeze_final_send_allowed_count =
                        repair_hard_freeze_final_send_allowed_count.saturating_add(selected_count);
                    match repair_same_snapshot_hard_freeze.miss_reason(
                        $ack_epoch,
                        $snapshot_ranges,
                        tx_count,
                    ) {
                        "no_coverage" => {
                            repair_hard_freeze_miss_reason_no_coverage =
                                repair_hard_freeze_miss_reason_no_coverage
                                    .saturating_add(selected_count);
                        }
                        "snapshot_changed" => {
                            repair_hard_freeze_miss_reason_snapshot_changed =
                                repair_hard_freeze_miss_reason_snapshot_changed
                                    .saturating_add(selected_count);
                            repair_missing_digest_freeze_allow_new_digest_count =
                                repair_missing_digest_freeze_allow_new_digest_count
                                    .saturating_add(selected_count);
                        }
                        "ack_epoch_changed" => {
                            repair_hard_freeze_miss_reason_ack_epoch_changed =
                                repair_hard_freeze_miss_reason_ack_epoch_changed
                                    .saturating_add(selected_count);
                        }
                        "ack_epoch_ignored" => {
                            repair_missing_digest_freeze_ack_epoch_ignored_count =
                                repair_missing_digest_freeze_ack_epoch_ignored_count
                                    .saturating_add(selected_count);
                            repair_missing_digest_stable_ack_refresh_count =
                                repair_missing_digest_stable_ack_refresh_count
                                    .saturating_add(selected_count);
                            repair_hard_freeze_miss_reason_no_overlap =
                                repair_hard_freeze_miss_reason_no_overlap
                                    .saturating_add(selected_count);
                        }
                        _ => {
                            repair_hard_freeze_miss_reason_no_overlap =
                                repair_hard_freeze_miss_reason_no_overlap
                                    .saturating_add(selected_count);
                        }
                    }
                }
            }
        }};
    }
